/* ===================== BÀI 29 · INT và bảng vector ===================== */
/* Bài 29 · INT và bảng vector (AMTS-EMB-002-M08-L01, X86-029) — sinh bởi tools/author/mpu8086/l29.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P29=[{"label": "Ví dụ: tự cài vectơ 60h rồi gọi INT 60h", "code": "; Ví dụ 1: tự cài vectơ 60h rồi gọi INT 60h\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AX, 0\n        MOV     ES, AX                  ; ES = 0000h: đoạn của bảng vectơ\n        MOV     WORD PTR ES:[180H], OFFSET NHAN2 ; 60h × 4\n        MOV     ES:[182H], CS           ; word sau: đoạn của chương trình\n        MOV     AL, 21\n        INT     60H                     ; cất FLAGS, CS, IP rồi nhảy\n        MOV     DL, AL                  ; AL = 42 = '*'\n        MOV     AH, 02H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\nNHAN2   PROC                            ; trình phục vụ ngắt 60h\n        ADD     AL, AL                  ; AL = AL × 2\n        IRET                            ; lấy lại IP, CS, FLAGS\nNHAN2   ENDP\n        END     MAIN\n", "input": "", "note": "Bấm Từng bước. Hai lệnh MOV ghi 4 byte vào 0000:0180h (chọn vùng IVT ở phần Bộ nhớ để xem 20 00 10 07). Lệnh INT 60h (51 chu kỳ): phần Ngăn xếp hiện ba word FLAGS F202h, CS 0710h, IP 0015h; IF ở phần Thanh ghi về 0. ADD AL, AL cho AL = 42 = '*'; IRET (24 chu kỳ) đưa CS:IP về 0710:0015 và IF = 1. Đoán trước: ngay sau INT 60h, SP bằng bao nhiêu? Đáp án 00FAh."}, {"label": "Ví dụ: đọc vectơ 21h bằng hai cách", "code": "; Ví dụ 2: hai cách đọc vectơ 21h\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nv_off   DW      ?                       ; đọc thẳng từ bảng vectơ\nv_seg   DW      ?\nd_off   DW      ?                       ; đọc bằng INT 21h hàm 35h\nd_seg   DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 0\n        MOV     ES, AX                  ; ES = 0000h\n        MOV     AX, ES:[84H]            ; 21h × 4 = 84h: offset\n        MOV     v_off, AX\n        MOV     AX, ES:[86H]            ; 86h: đoạn\n        MOV     v_seg, AX\n        MOV     AX, 3521H               ; AH = 35h, AL = số vectơ 21h\n        INT     21H                     ; trả về ES:BX\n        MOV     d_off, BX\n        MOV     d_seg, ES\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Đọc vectơ 21h hai cách: thẳng từ 0000:0084h (MOV AX, ES:[84h] dạng A1, 10 + 2 chu kỳ tiền tố ES) và bằng INT 21h hàm 35h (trả ES:BX). Bốn biến đều cho F000:0084h, là vectơ mặc định của trình mô phỏng (trên PC thật là địa chỉ trong DOS, tùy máy). Đoán trước: sau INT 21h hàm 35h, ES bằng bao nhiêu? Đáp án F000h."}, {"label": "Ví dụ: hàm 25h/35h, cất và trả lại vectơ", "code": "; Ví dụ 3: cài bằng hàm 25h, cất và trả lại vectơ cũ\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ncu_off  DW      ?\ncu_seg  DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 3560H               ; đọc vectơ 60h cũ → ES:BX\n        INT     21H\n        MOV     cu_off, BX\n        MOV     cu_seg, ES\n        PUSH    DS\n        PUSH    CS\n        POP     DS                      ; hàm 25h lấy địa chỉ ở DS:DX\n        MOV     DX, OFFSET NHAN2\n        MOV     AX, 2560H               ; AH = 25h, AL = 60h\n        INT     21H\n        POP     DS\n        MOV     AL, 33\n        INT     60H                     ; AL = 66 = 'B'\n        MOV     DL, AL\n        MOV     AH, 02H\n        INT     21H\n        PUSH    DS\n        MOV     DX, cu_off              ; trả lại vectơ cũ\n        MOV     DS, cu_seg\n        MOV     AX, 2560H\n        INT     21H\n        POP     DS\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\nNHAN2   PROC\n        ADD     AL, AL\n        IRET\nNHAN2   ENDP\n        END     MAIN\n", "input": "", "note": "Cách làm đúng phép lịch sự: hàm 35h cất vectơ 60h cũ (F000:0180h) vào cu_off, cu_seg; hàm 25h cài NHAN2 (phải đặt DS = CS vì hàm 25h lấy địa chỉ ở DS:DX, nên PUSH DS / PUSH CS / POP DS rồi POP DS); gọi INT 60h in B; cuối cùng nạp DS:DX từ cu_seg, cu_off và gọi hàm 25h lần nữa. Xem 0000:0180h trở về 80 01 00 F0. Đoán trước: ngay trước lệnh INT 21h đầu tiên có AH = 25h, DS bằng bao nhiêu? Đáp án 0710h (= CS)."}, {"label": "Lỗi: trình phục vụ kết thúc bằng RET", "code": "; Ví dụ 4: LỖI - trình phục vụ ngắt kết thúc bằng RET\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AX, 0\n        MOV     ES, AX\n        MOV     WORD PTR ES:[180H], OFFSET NHAN2\n        MOV     ES:[182H], CS\n        MOV     CX, 3\nLAP:\n        MOV     AL, CL\n        INT     60H                     ; cất 6 byte\n        LOOP    LAP\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\nNHAN2   PROC\n        ADD     AL, AL\n        RET                             ; sai: chỉ lấy lại IP (2 byte)\nNHAN2   ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: NHAN2 kết thúc bằng RET (C3) thay vì IRET. INT 60h cất 6 byte, RET chỉ lấy 2 byte (IP). Chương trình vẫn chạy tiếp đúng chỗ vì trình phục vụ cùng đoạn với chỗ gọi, nhưng sau 3 vòng SP từ 0100h xuống 00F4h (12 byte rác trên Ngăn xếp) và IF kẹt ở 0. Sửa: đổi RET thành IRET. Đoán trước: sau lần RET đầu tiên, SP bằng bao nhiêu? Đáp án 00FCh."}, {"label": "Ví dụ: tự xử lý lỗi chia (ngắt loại 0)", "code": "; Ví dụ 5: tự xử lý lỗi chia (ngắt loại 0)\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntb      DB      'Loi chia! $'\nxong    DB      'Xong$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 0\n        MOV     ES, AX\n        PUSH    WORD PTR ES:[0]         ; cất vectơ 0 cũ lên ngăn xếp\n        PUSH    WORD PTR ES:[2]\n        MOV     WORD PTR ES:[0], OFFSET LOICHIA ; vectơ 0\n        MOV     ES:[2], CS\n        MOV     AX, 7\n        MOV     BL, 0\n        DIV     BL                      ; chia cho 0 → ngắt 0\n        MOV     DX, OFFSET xong         ; 8086: IRET quay về lệnh này\n        MOV     AH, 09H\n        INT     21H\n        POP     WORD PTR ES:[2]         ; trả lại vectơ 0 cũ\n        POP     WORD PTR ES:[0]\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\nLOICHIA PROC\n        PUSH    AX\n        PUSH    DX\n        MOV     DX, OFFSET tb\n        MOV     AH, 09H\n        INT     21H                     ; gọi DOS từ trong trình phục vụ\n        POP     DX\n        POP     AX\n        IRET\nLOICHIA ENDP\n        END     MAIN\n", "input": "", "note": "DIV BL với BL = 0 gây ngắt loại 0. Vectơ 0 cũ được cất lên ngăn xếp bằng PUSH WORD PTR ES:[0] / ES:[2] (24 chu kỳ mỗi lệnh), rồi trỏ tới LOICHIA. Trình phục vụ gọi INT 21h hàm 09h in thông báo, giữ AX, DX, rồi IRET. Trên 8086, CPU đã cất địa chỉ của lệnh SAU DIV, nên chương trình in tiếp Xong. Cuối chương trình POP trả lại vectơ 0 (xem 0000:0000h). Trình mô phỏng ghi 80 chu kỳ cho DIV (cận dưới của khoảng 80–90) và chưa cộng thời gian CPU vào ngắt 0. Đoán trước: IRET quay về lệnh nào? Đáp án MOV DX, OFFSET xong."}, {"label": "Lỗi: trình phục vụ làm hỏng DL", "code": "; Ví dụ 6: LỖI - trình phục vụ làm hỏng thanh ghi\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AX, 0\n        MOV     ES, AX\n        MOV     WORD PTR ES:[180H], OFFSET DOI\n        MOV     ES:[182H], CS\n        MOV     DL, 'K'                 ; ký tự cần in\n        MOV     AL, 'a'\n        INT     60H                     ; đổi AL thành chữ hoa\n        MOV     BL, AL                  ; giữ kết quả\n        MOV     AH, 02H\n        INT     21H                     ; mong in K\n        MOV     DL, BL\n        INT     21H                     ; mong in A\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\nDOI     PROC\n        MOV     DL, 20H                 ; dùng DL mà không cất\n        SUB     AL, DL                  ; 'a' - 20h = 'A'\n        IRET\nDOI     ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: trình phục vụ DOI dùng DL làm chỗ chứa 20h mà không cất. Chương trình chính đã đặt DL = 'K' trước INT 60h nên lần in đầu ra dấu cách thay vì K. Sửa: PUSH DX ở đầu trình phục vụ và POP DX trước IRET, hoặc dùng SUB AL, 20h không cần thanh ghi phụ. Đoán trước: sau IRET, DL bằng bao nhiêu (hệ 16)? Đáp án 20h."}, {"label": "Ví dụ: INT so với PUSHF + CALL xa", "code": "; Ví dụ 7: INT so với PUSHF + CALL FAR\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AX, 0\n        MOV     ES, AX\n        MOV     WORD PTR ES:[180H], OFFSET NHAN2\n        MOV     ES:[182H], CS\n        MOV     AL, 3\n        INT     60H                     ; cách 1: 2 byte\n        PUSHF                           ; cách 2: tự cất FLAGS\n        CALL    FAR PTR NHAN2           ; rồi CALL xa (5 byte)\n        MOV     AH, 4CH                 ; AL = 12 làm mã thoát\n        INT     21H\nMAIN    ENDP\nNHAN2   PROC\n        ADD     AL, AL\n        IRET\nNHAN2   ENDP\n        END     MAIN\n", "input": "", "note": "Cùng trình phục vụ NHAN2 gọi hai cách. INT 60h: 2 byte, 51 + 24 = 75 chu kỳ cho gọi và trở về. PUSHF + CALL FAR PTR NHAN2: 1 + 5 = 6 byte, 10 + 28 + 24 = 62 chu kỳ; ba word trên ngăn xếp giống hệt INT nên IRET vẫn đúng (khác ở chỗ PUSHF không xóa IF). Mã máy 9A 1F 00 10 07 chứa sẵn đoạn 0710h do bộ nạp sửa lúc nạp. AL = 3 × 2 × 2 = 12 thành mã thoát. Đoán trước: ngay sau CALL FAR, SP bằng bao nhiêu? Đáp án 00FAh."}];
const sim29=makeX86Sim(document.getElementById("x86-l29"),{id:"s29",presets:P29,file:"BAI29.ASM"});
makeX86Ex(document.getElementById("ex-l29"),sim29,[{"t": "Cài vectơ 60h cho trình phục vụ HOA", "d": "Chương trình đọc phím bằng INT 21h hàm 08h tới khi gặp dấu chấm, mỗi phím gọi INT 60h để đổi chữ thường a–z thành chữ hoa (ký tự khác giữ nguyên) rồi in bằng hàm 02h. Trình phục vụ HOA đã viết sẵn, nhưng vectơ 60h chưa được cài. Hãy: (1) cất vectơ 60h cũ (word ở 0000:0180h và 0000:0182h) vào biến cu_off, cu_seg; (2) ghi offset của HOA vào 0000:0180h, đoạn CS vào 0000:0182h; (3) trước khi kết thúc, trả lại vectơ cũ. Kết thúc bằng INT 21h hàm 4Ch. Trên trình mô phỏng, vectơ 60h ban đầu là F000:0180h (giả định của trình mô phỏng), nên trình chấm kiểm cu_off = 0180h, cu_seg = F000h.", "start": "; Bài tập 1: cài vectơ 60h cho trình phục vụ HOA\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ncu_off  DW      ?                       ; offset cũ của vectơ 60h\ncu_seg  DW      ?                       ; đoạn cũ của vectơ 60h\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 0\n        MOV     ES, AX                  ; ES = 0000h (bảng vectơ)\n; TODO: cất vectơ 60h cũ vào cu_off, cu_seg\n; TODO: ghi offset, đoạn của HOA vào vectơ 60h\nDOC:\n        MOV     AH, 08H\n        INT     21H                     ; AL = phím\n        CMP     AL, '.'\n        JE      HET\n        INT     60H                     ; AL → chữ hoa\n        MOV     DL, AL\n        MOV     AH, 02H\n        INT     21H\n        JMP     DOC\nHET:\n; TODO: trả lại vectơ 60h cũ\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\nHOA     PROC                            ; vào: AL; ra: AL (a–z → A–Z)\n        CMP     AL, 'a'\n        JB      XONG\n        CMP     AL, 'z'\n        JA      XONG\n        SUB     AL, 20H\nXONG:\n        IRET\nHOA     ENDP\n        END     MAIN\n", "tests": [{"in": "abc.", "out": "ABC", "mem": [{"at": "cu_off", "bytes": [128, 1]}, {"at": "cu_seg", "bytes": [0, 240]}]}, {"in": "Xin chao.", "out": "XIN CHAO", "mem": [{"at": "cu_off", "bytes": [128, 1]}, {"at": "cu_seg", "bytes": [0, 240]}]}, {"in": "8086 asm.", "out": "8086 ASM", "mem": [{"at": "cu_off", "bytes": [128, 1]}, {"at": "cu_seg", "bytes": [0, 240]}]}, {"in": ".", "out": "", "mem": [{"at": "cu_off", "bytes": [128, 1]}, {"at": "cu_seg", "bytes": [0, 240]}]}, {"in": "az{`@.", "out": "AZ{`@", "mem": [{"at": "cu_off", "bytes": [128, 1]}, {"at": "cu_seg", "bytes": [0, 240]}]}, {"in": "MiXeD.", "out": "MIXED", "mem": [{"at": "cu_off", "bytes": [128, 1]}, {"at": "cu_seg", "bytes": [0, 240]}]}]}, {"t": "Tự bắt lỗi chia", "d": "Đọc hai chữ số a rồi b bằng INT 21h hàm 08h (không hiện), tính a chia b bằng DIV BL. Nếu chia được, in q=thương r=dư (ví dụ 8 và 3 cho q=2 r=2); nếu b = 0, in Loi chia. Yêu cầu: không kiểm b = 0 trước khi chia, mà cài trình phục vụ của mình cho ngắt loại 0 (vectơ ở 0000:0000h) để đặt biến loi = 1; chương trình chính xem loi sau lệnh DIV. Cất vectơ 0 cũ trước khi cài và trả lại trước khi kết thúc bằng INT 21h hàm 4Ch. Trên 8086, sau lỗi chia, IRET quay về lệnh ngay sau DIV.", "start": "; Bài tập 2: tự bắt lỗi chia\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nloi     DB      0                       ; 1 nếu vừa có lỗi chia\ntbq     DB      'q=$'\ntbr     DB      ' r=$'\ntbl     DB      'Loi chia$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n; TODO: cài vectơ 0 trỏ tới BATLOI (nhớ cất vectơ cũ)\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'\n        MOV     CL, AL                  ; CL = a\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'\n        MOV     BL, AL                  ; BL = b\n        MOV     AL, CL\n        MOV     AH, 0                   ; AX = a\n        DIV     BL                      ; AL = thương, AH = dư\n        CMP     loi, 1\n        JE      BAO\n        MOV     CX, AX                  ; giữ thương, dư\n        MOV     DX, OFFSET tbq\n        MOV     AH, 09H\n        INT     21H\n        MOV     DL, CL\n        ADD     DL, '0'\n        MOV     AH, 02H\n        INT     21H\n        MOV     DX, OFFSET tbr\n        MOV     AH, 09H\n        INT     21H\n        MOV     DL, CH\n        ADD     DL, '0'\n        MOV     AH, 02H\n        INT     21H\n        JMP     KETTHUC\nBAO:\n        MOV     DX, OFFSET tbl\n        MOV     AH, 09H\n        INT     21H\nKETTHUC:\n; TODO: trả lại vectơ 0 cũ\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\nBATLOI  PROC\n; TODO: đặt loi = 1\n        IRET\nBATLOI  ENDP\n        END     MAIN\n", "tests": [{"in": "82", "out": "q=4 r=0", "mem": [{"at": "loi", "bytes": [0]}]}, {"in": "93", "out": "q=3 r=0", "mem": [{"at": "loi", "bytes": [0]}]}, {"in": "70", "out": "Loi chia", "mem": [{"at": "loi", "bytes": [1]}]}, {"in": "00", "out": "Loi chia", "mem": [{"at": "loi", "bytes": [1]}]}, {"in": "19", "out": "q=0 r=1", "mem": [{"at": "loi", "bytes": [0]}]}, {"in": "99", "out": "q=1 r=0", "mem": [{"at": "loi", "bytes": [0]}]}, {"in": "57", "out": "q=0 r=5", "mem": [{"at": "loi", "bytes": [0]}]}]}, {"t": "Trình phục vụ HEX gọn", "d": "Chương trình chính (đã viết, không cần sửa) đọc phím tới dấu chấm, lấy nửa thấp của mã phím (0–15), gọi INT 60h để đổi thành chữ số hệ 16 '0'–'9', 'A'–'F' rồi in. Trình phục vụ HEX phải trả kết quả trong AL và giữ nguyên mọi thanh ghi khác (trình chấm kiểm BX, CX, SI, DI, BP lúc kết thúc). Bản mẫu cất cả 8 thanh ghi nên đúng nhưng chậm. Viết lại HEX để chương trình chạy không quá 4400 chu kỳ ở test dài nhất (16 phím) và mã không quá 72 byte.", "start": "; Bài tập 3: trình phục vụ HEX gọn (chỉ được đổi AL)\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nhexso   DB      '0123456789ABCDEF'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 0\n        MOV     ES, AX\n        MOV     WORD PTR ES:[180H], OFFSET HEX\n        MOV     ES:[182H], CS\n        MOV     BX, 1234H               ; các thanh ghi phải giữ nguyên\n        MOV     CX, 5678H\n        MOV     SI, 9ABCH\n        MOV     DI, 0DEF0H\n        MOV     BP, 4321H\nDOC:\n        MOV     AH, 08H\n        INT     21H\n        CMP     AL, '.'\n        JE      HET\n        AND     AL, 0FH                 ; nửa thấp của mã phím\n        INT     60H                     ; AL → ký tự hệ 16\n        MOV     DL, AL\n        MOV     AH, 02H\n        INT     21H\n        JMP     DOC\nHET:\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\nHEX     PROC                            ; vào AL = 0..15, ra AL = '0'..'F'\n        PUSH    BX                      ; cất hết cho chắc: đúng nhưng chậm\n        PUSH    CX\n        PUSH    DX\n        PUSH    SI\n        PUSH    DI\n        PUSH    BP\n        PUSH    DS\n        PUSH    ES\n        MOV     BX, OFFSET hexso\n        XLAT                            ; AL = [BX + AL]\n        POP     ES\n        POP     DS\n        POP     BP\n        POP     DI\n        POP     SI\n        POP     DX\n        POP     CX\n        POP     BX\n        IRET\nHEX     ENDP\n        END     MAIN\n", "tests": [{"in": "09.", "out": "09", "regs": {"BX": 4660, "CX": 22136, "SI": 39612, "DI": 57072, "BP": 17185}}, {"in": "AZ.", "out": "1A", "regs": {"BX": 4660, "CX": 22136, "SI": 39612, "DI": 57072, "BP": 17185}}, {"in": "0123456789:;<=>?.", "out": "0123456789ABCDEF", "regs": {"BX": 4660, "CX": 22136, "SI": 39612, "DI": 57072, "BP": 17185}}, {"in": ".", "out": "", "regs": {"BX": 4660, "CX": 22136, "SI": 39612, "DI": 57072, "BP": 17185}}, {"in": "Ok!.", "out": "FB1", "regs": {"BX": 4660, "CX": 22136, "SI": 39612, "DI": 57072, "BP": 17185}}, {"in": "pP_.", "out": "00F", "regs": {"BX": 4660, "CX": 22136, "SI": 39612, "DI": 57072, "BP": 17185}}], "perf": {"cycles": 4400, "bytes": 72}}]);

makeQuiz("quiz29","score29",[{"q": "Vectơ của ngắt loại 21h nằm ở đâu và word nào là đoạn?", "o": ["0000:0021h–0024h; word ở 0023h là đoạn", "0000:0084h–0087h; word ở 0086h là đoạn", "0000:0084h–0087h; word ở 0084h là đoạn", "F000:0084h; vectơ nằm trong ROM BIOS"], "a": 1, "e": "Vectơ n ở n × 4 = 21h × 4 = 84h; word đầu (84h) là offset, word sau (86h) là đoạn. F000:0084h là giá trị của vectơ trên trình mô phỏng (nơi trình phục vụ nằm), không phải chỗ chứa vectơ."}, {"q": "SP = 0100h, FLAGS = F202h. Lệnh <code>INT 60h<\/code> ở 0710:0013h (2 byte). Ngay khi trình phục vụ bắt đầu, phát biểu nào đúng?", "o": ["SP = 00FCh; word ở SS:00FCh là 0015h; IF = 1", "SP = 00FAh; word ở SS:00FAh là 0015h; IF = 0", "SP = 00FAh; word ở SS:00FAh là 0013h; IF = 0", "SP = 00FAh; word ở SS:00FAh là F202h; IF = 1"], "a": 1, "e": "INT cất FLAGS, CS, IP (của lệnh kế tiếp 0013h + 2 = 0015h) theo thứ tự đó, nên IP nằm ở đỉnh (SP − 6 = 00FAh). INT xóa IF và TF trước khi vào trình phục vụ."}, {"q": "Trình phục vụ ngắt kết thúc bằng <code>RET<\/code> (gần) thay vì <code>IRET<\/code>, và nằm cùng đoạn với chỗ gọi. Điều gì xảy ra?", "o": ["Chương trình chạy tiếp đúng chỗ nhưng mỗi lần gọi để lại 4 byte trên ngăn xếp và IF vẫn là 0", "CPU báo lỗi ngay vì INT bắt buộc đi với IRET", "Chương trình nhảy về địa chỉ 0000:0000 vì RET lấy nhầm word cờ", "Không có khác biệt vì RET và IRET đều lấy IP và CS"], "a": 0, "e": "RET gần chỉ POP IP (word ở đỉnh), nên quay về đúng lệnh sau INT; CS cũ và FLAGS còn trên ngăn xếp, cờ không được khôi phục (IF = 0 do INT đã xóa). CPU không kiểm tra cặp INT/IRET (Ví dụ 4)."}, {"q": "Trên 8086, sau <code>DIV BL<\/code> với BL = 0 và vectơ 0 trỏ tới trình phục vụ kết thúc bằng IRET, chương trình tiếp tục ở đâu?", "o": ["Chính lệnh DIV BL, nên lại chia cho 0 mãi", "Lệnh đầu chương trình", "Lệnh ngay sau DIV BL", "Không tiếp tục: lỗi chia luôn kết thúc chương trình"], "a": 2, "e": "8086/8088 cất địa chỉ của lệnh kế tiếp khi lỗi chia; từ 80286 trở đi CPU cất địa chỉ của chính lệnh DIV. DOS mặc định in thông báo và dừng chương trình, nhưng khi bạn tự cài vectơ 0 thì IRET quay về sau DIV (Ví dụ 5)."}, {"q": "Trình phục vụ chỉ dùng BX để tra bảng và trả kết quả trong AL. Cách nào giữ đúng mọi thanh ghi khác mà tốn ít chu kỳ nhất?", "o": ["PUSH AX, BX, CX, DX ở đầu, POP theo thứ tự ngược", "PUSHF ở đầu, POPF trước IRET", "Không cất gì, vì IRET tự khôi phục mọi thanh ghi", "PUSH BX ở đầu, POP BX trước IRET"], "a": 3, "e": "Chỉ cần cất thanh ghi bị dùng: 11 + 8 = 19 chu kỳ. Cất AX còn làm mất kết quả trong AL. PUSHF/POPF không giữ BX; IRET chỉ khôi phục IP, CS, FLAGS."}]);

